function addAbsolute() {
  const items = document.getElementsByClassName("newsItem");
  for (let i = 0; i < items.length; i++) {
    const height = items[i].clientHeight;
    if (height == 153) {
      const time = items[i].getElementsByClassName("newsRightConTime")[0];
      time.classList.add("absoluteTime");
    }
  }
}
addAbsolute();

let start = 20;
const count = 20;
let isLoading = false;

const getList = (num,subject) => {
  if (!isLoading) {
    isLoading = true;
    return new Promise((resolve) => {
      $.ajax({
        url: `https://gateway.caixin.com/api/extapi/homeInterface.jsp?start=${num}&subject=${subject}&type=0&count=${count}&picdim=_266_177&_=1693204776970`,
        dataType: "jsonp",
        success(data) {
          isLoading = false;
          start += count;
          resolve(data);
        },
      });
    });
  }
  return null;
};

function formatCustomDate(inputDate) {
  var parts = inputDate.split(/[- :]/);
  var dateObj = new Date(parts[0], parts[1] - 1, parts[2], parts[3], parts[4], parts[5]);

  var year = dateObj.getFullYear();
  var month = String(dateObj.getMonth() + 1).padStart(2, '0');
  var day = String(dateObj.getDate()).padStart(2, '0');
  var hours = String(dateObj.getHours()).padStart(2, '0');
  var minutes = String(dateObj.getMinutes()).padStart(2, '0');

  return year + "年" + month + "月" + day + "日 " + hours + ":" + minutes;
}

